fn rolling_max(numbers: Vec<i32>) -> Vec<i32> {
    let mut result = Vec::with_capacity(numbers.len());
    let mut current_max: Option<i32> = None;

    for &num in &numbers {
        current_max = Some(match current_max {
            None => num,
            Some(max_val) => if num > max_val { num } else { max_val },
        });
        // Since current_max is Some now, unwrap is safe.
        result.push(current_max.unwrap());
    }

    result
}